package com.example

/**
 * 20 completely distinct, syllabus-aligned structured question templates tailored precisely to each subject
 * (History, Buddhism, Sinhala, Civics, Geography, Commerce, Science, Math, ICT, English).
 * Guarantees zero cross-contamination (e.g. no science formulas in History).
 */
object StructuredQuestionBankTemplates {

  fun getStructuredSubQuestions(
    subject: String,
    cleanTheme: String,
    qIndex: Int,
    setNumber: Int
  ): List<StructuredSubQuestion> {
    val q = qIndex.coerceIn(1, 20)

    return when {
      subject.contains("ඉතිහාසය") -> getHistorySubQuestions(cleanTheme, q)
      subject.contains("බුද්ධ ධර්මය") -> getBuddhismSubQuestions(cleanTheme, q)
      subject.contains("සිංහල") -> getSinhalaSubQuestions(cleanTheme, q)
      subject.contains("පුරවැසි අධ්‍යාපනය") -> getCivicsSubQuestions(cleanTheme, q)
      subject.contains("භූගෝල විද්‍යාව") -> getGeographySubQuestions(cleanTheme, q)
      subject.contains("ව්‍යාපාර හා ගිණුම්කරණය") -> getCommerceSubQuestions(cleanTheme, q)
      subject.contains("විද්‍යාව") -> getScienceSubQuestions(cleanTheme, q)
      subject.contains("ගණිතය") -> getMathSubQuestions(cleanTheme, q)
      subject.contains("ICT") -> getIctSubQuestions(cleanTheme, q)
      else -> getGeneralSubQuestions(cleanTheme, q)
    }
  }

  private fun getHistorySubQuestions(theme: String, q: Int): List<StructuredSubQuestion> {
    return when (q % 5) {
      1 -> listOf(
        StructuredSubQuestion("(i)", "$theme යුගයට හෝ ඓතිහාසික සිදුවීමට අදාළ කාලසීමාව සහ ප්‍රධාන පාලකයා නම් කරන්න.", 3, "ප්‍රධාන පාලකයාගේ නම සහ ඓතිහාසික කාලවකවානුව නිවැරදිව දැක්වීම.", listOf("පාලකයා නම් කිරීම (ලකුණු 2)", "කාලසීමාව (ලකුණු 1)")),
        StructuredSubQuestion("(ii)", "එම යුගයේ පැවති ප්‍රධාන පරිපාලන හෝ ආර්ථික ලක්ෂණ 2ක් ලියන්න.", 4, "1. මධ්‍යගත රාජ්‍ය පාලන ක්‍රමය.\n2. වැව් සහ අමුණු මුල් කරගත් ගොවිජන ආර්ථිකය.", listOf("පළමු ලක්ෂණය (ලකුණු 2)", "දෙවන ලක්ෂණය (ලකුණු 2)")),
        StructuredSubQuestion("(iii)", "මෙම ඓතිහාසික යුගය තහවුරු කිරීමට ඉතිහාසඥයින් භාවිතා කරන ප්‍රධාන පුරාවිද්‍යාත්මක මූලාශ්‍රයක් නම් කරන්න.", 4, "සෙල්ලිපි, ටැම්ලිපි හෝ ඉදි කරන ලද ස්තූප හා වැව් සංකීර්ණ.", listOf("මූලාශ්‍රය නම් කිරීම (ලකුණු 2)", "එහි වැදගත්කම (ලකුණු 2)")),
        StructuredSubQuestion("(iv)", "මෙරට ශිෂ්ටාචාරයට මෙම යුගයෙන් ලැබුණු අමරණීය දායකත්වය එක් වාක්‍යයකින් විග්‍රහ කරන්න.", 4, "ස්වයංපෝෂිත වාරි සංස්කෘතියක් සහ විශිෂ්ට කලා මංජුසාවක් රටට දායාද කිරීම.", listOf("දායකත්වය විග්‍රහ කිරීම (ලකුණු 4)"))
      )
      2 -> listOf(
        StructuredSubQuestion("(i)", "$theme ආශ්‍රිතව ලෝක ඉතිහාසයේ හෝ මෙරට ඉතිහාසයේ සිදුවූ ප්‍රධාන සංක්‍රාන්ති සමය කුමක්ද?", 3, "දේශපාලනික, සමාජීය හෝ ආර්ථික පෙරළියක් සිදු වූ නිශ්චිත යුගය හැඳින්වීම.", listOf("සංක්‍රාන්ති සමය නම් කිරීම (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "එම පෙරළියට මුල් වූ අභ්‍යන්තර හෝ බාහිර සාධක 2ක් නම් කරන්න.", 4, "1. විදේශීය ආක්‍රමණ හෝ වෙළඳ සබඳතා පුළුල් වීම.\n2. අභ්‍යන්තර බල අරගල සහ ආගමික පුනර්ජීවනය.", listOf("පළමු සාධකය (ලකුණු 2)", "දෙවන සාධකය (ලකුණු 2)")),
        StructuredSubQuestion("(iii)", "මෙම සිදුවීම නිසා සාමාන්‍ය ජනජීවිතයට ඇති වූ සෘජු බලපෑම කුමක්ද?", 4, "ගම්මානවල ස්වයංපෝෂිතභාවය බිඳවැටීම හෝ නව වෙළඳ නගර බිහිවීම.", listOf("බලපෑම පැහැදිලි කිරීම (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "මෙම ඓතිහාසික සිදුවීමෙන් වර්තමාන සමාජයට ගත හැකි වැදගත් පාඩම කුමක්ද?", 3, "ජාතික ස්වෛරීභාවය ආරක්ෂා කරගැනීමේ සහ විදේශ සබඳතා බුද්ධිමත්ව පවත්වාගැනීමේ අවශ්‍යතාව.", listOf("ඉතිහාස පාඩම (ලකුණු 3)"))
      )
      3 -> listOf(
        StructuredSubQuestion("(i)", "$theme යුගයේ පැවති ප්‍රධාන ආගමික හා සංස්කෘතික පසුබිම කෙටියෙන් හඳුන්වා දෙන්න.", 3, "ථේරවාදී බුදුදහම රාජ්‍ය ආගම වීම සහ බෞද්ධ සංස්කෘතිය සමාජයේ මුල් බැසගැනීම.", listOf("ආගමික පසුබිම (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "එම යුගයේ ඉදිකරන ලද විශිෂ්ට වාස්තු විද්‍යාත්මක නිර්මාණ 2ක් නම් කරන්න.", 4, "1. අනුරාධපුර යුගයේ මහා ස්තූප (අභයගිරිය, ජේතවනාරාමය).\n2. සීගිරිය හෝ පොළොන්නරුවේ සඳමඩප හා වාමන රූප.", listOf("පළමු නිර්මාණය (ලකුණු 2)", "දෙවන නිර්මාණය (ලකුණු 2)")),
        StructuredSubQuestion("(iii)", "පෞරාණික වැව් සහ ජල කළමනාකරණ පද්ධතියේ ප්‍රධාන ඉංජිනේරු ලක්ෂණය කුමක්ද?", 4, "බිසෝකොටුව, විශාල වන බැමි සහ ඇළ මාර්ග හරහා ජලය ක්‍රමානුකූලව බෙදාහැරීම.", listOf("ඉංජිනේරු ලක්ෂණය (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "අතීත වාරි ශිෂ්ටාචාරය වර්තමාන සංවර්ධනයට ආදර්ශයක් වන්නේ කෙසේද?", 4, "පරිසර හිතකාමී ලෙස ජල සම්පත සංරක්ෂණය කිරීම සහ තිරසාර කෘෂිකර්මාන්තය පවත්වා ගැනීම.", listOf("ආදර්ශය පැහැදිලි කිරීම (ලකුණු 4)"))
      )
      4 -> listOf(
        StructuredSubQuestion("(i)", "$theme සමයේ මෙරට විදෙස් වෙළඳ සබඳතා පැවැත්වූ ප්‍රධාන රටවල් හෝ අධිරාජ්‍යයන් 2ක් නම් කරන්න.", 3, "ඉන්දියාව, චීනය, රෝමය සහ මැදපෙරදිග රටවල්.", listOf("පළමු රට (ලකුණු 1.5)", "දෙවන රට (ලකුණු 1.5)")),
        StructuredSubQuestion("(ii)", "මෙරටින් අපනයනය කරන ලද ප්‍රධාන භාණ්ඩ 2ක් ලියන්න.", 4, "1. මුතු සහ මැණික්.\n2. කුළුබඩු (කරදමුංගු, මිරිස්, කුරුඳු) සහ ඇبنොයිස් දැව.", listOf("පළමු අපනයනය (ලකුණු 2)", "දෙවන අපනයනය (ලකුණු 2)")),
        StructuredSubQuestion("(iii)", "වෙළඳාම නිසා මෙරටට ලැබුණු ආර්ථික හා සමාජීය වාසිය කුමක්ද?", 4, "භාණ්ඩාගාරයට ආදායම් ලැබීම සහ විවිධ සංස්කෘතික අංග රටට එකතු වීම.", listOf("වාසිය පැහැදිලි කිරීම (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "ප්‍රාග්ධන සමුච්චයනය සහ වෙළඳ නගර (Emporiums) බිහිවීමට මුල් වූ වරාය නගරය කුමක්ද?", 3, "මහාතිර්ථ (මාතොට) හෝ ගෝකණ්ණ වරාය.", listOf("වරාය නම් කිරීම (ලකුණු 3)"))
      )
      else -> listOf(
