        StructuredSubQuestion("(iii)", "සිංහල භාෂාවේ පවතින නියමිත සංස්කෘත සහ පාලි තත්භව පද හඳුනාගැනීමේ ක්‍රමය ලියන්න.", 4, "අකුරු යෙදෙන ආකාරය සහ උච්චාරණ විධි පරීක්ෂා කිරීම.", listOf("හඳුනාගැනීමේ ක්‍රමය (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "මාතෘකාවට අදාළව ඡේද සැලසුම් කිරීමේදී අනුගමනය කළ යුතු පිළිවෙළ දක්වන්න.", 3, "පූර්විකාව, ප්‍රධාන විෂය ධාතුව සහ අවසාන නිගමනය.", listOf("ඡේද පිළිවෙළ (ලකුණු 3)"))
      )
      else -> listOf(
        StructuredSubQuestion("(i)", "$theme වාක්‍ය විමසීමේදී (පදගත කිරීම, කාරක මාරු කිරීම) අදාළ ව්‍යාකරණ රීතිය ලියන්න.", 3, "කතෘ, කර්ම, ක්‍රියා පදවල ගැළපීම.", listOf("ව්‍යාකරණ රීතිය (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "සන්ධි සහ සමාස පද වෙන් කර පෙන්වන ආකාරය උදාහරණ සහිතව දක්වන්න.", 4, "පද දෙකක් එකතු වන විට සිදුවන ස්වර හෝ ව්යාංජන විපර්යාසය.", listOf("සන්ධි නීතිය (ලකුණු 2)", "සමාස විග්‍රහය (ලකුණු 2)")),
        StructuredSubQuestion("(iii)", "පද්‍යයක අර්ථය පැහැදිලි කිරීමේදී (පදපදය අර්ථය) සැලකිය යුතු කරුණු මොනවාද?", 4, "අන්වය කර ගැනීම සහ නියමිත පාරිභාෂික අර්ථය දීම.", listOf("අන්වය කිරීම (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "මව්බස මනාව හැසිරවීම බුද්ධි වර්ධනයට බලපාන්නේ කෙසේද?", 4, "නිවැරදිව සිතීමට, තර්ක කිරීමට සහ අදහස් ප්‍රකාශ කිරීමට ඇති හැකියාව දියුණු වීම.", listOf("බුද්ධි වර්ධනය (ලකුණු 4)"))
      )
    }
  }

  private fun getCivicsSubQuestions(theme: String, q: Int): List<StructuredSubQuestion> {
    return when (q % 5) {
      1 -> listOf(
        StructuredSubQuestion("(i)", "$theme පුරවැසි අධ්‍යාපන සංකල්පය හෝ ආණ්ඩුක්‍රම ව්‍යවස්ථා ප්‍රතිපාදනය නිර්වචනය කරන්න.", 3, "ප්‍රජාතන්ත්‍රවාදී සමාජයක මූලික අයිතිවාසිකම් සහ වගකීම්.", listOf("නිර්වචනය (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "එම සංකල්පයට අදාළ ප්‍රධාන ආයතන හෝ බලධාරීන් 2ක් නම් කරන්න.", 4, "1. පාර්ලිමේන්තුව සහ යුගෝචර අධිකරණ පද්ධතිය.\n2. මානව හිමිකම් කොමිෂන් සභාව.", listOf("පළමු ආයතනය (ලකුණු 2)", "දෙවන ආයතනය (ලකුණු 2)")),
        StructuredSubQuestion("(iii)", "පුරවැසියෙකු ලෙස අප සමාජයේ ඉටු කළ යුතු මූලික වගකීම් 2ක් ලියන්න.", 4, "නීතියට ගරු කිරීම, රාජ්‍ය දේපළ ආරක්ෂා කිරීම සහ අන් අයගේ අයිතිවාසිකම් සුරැකීම.", listOf("පළමු වගකීම (ලකුණු 2)", "දෙවන වගකීම (ලකුණු 2)")),
        StructuredSubQuestion("(iv)", "යහපත් පුරවැසියෙකු රටකට අවශ්‍ය වන්නේ ඇයි?", 3, "සාමය, සංවර්ධනය සහ සමාජ සාධාරණත්වය තහවුරු කිරීමට.", listOf("අවශ්‍යතාව (ලකුණු 3)"))
      )
      2 -> listOf(
        StructuredSubQuestion("(i)", "$theme ප්‍රජාතන්ත්‍රවාදී පාලන ක්‍රමයේ මූලික ලක්ෂණය හඳුන්වා දෙන්න.", 3, "ජනතා පරමාධිපත්‍යය සහ නීතියේ ආධිපත්‍යය.", listOf("මූලික ලක්ෂණය (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "මැතිවරණ ක්‍රමයක තිබිය යුතු ප්‍රධාන ලක්ෂණ 2ක් දක්වන්න.", 4, "නිදහස් හා සාධාරණ වීම සහ සියලු පුරවැසියන්ට ඡන්ද අයිතිය හිමිවීම.", listOf("පළමු ලක්ෂණය (ලකුණු 2)", "දෙවන ලක්ෂණය (ලකුණු 2)")),
        StructuredSubQuestion("(iii)", "ප්‍රජාතන්ත්‍රවාදයේ පැවැත්මට විපක්ෂයක ඇති කාර්යභාරය කුමක්ද?", 4, "ආණ්ඩුවේ අඩුපාඩු පෙන්වා දීම සහ විකල්ප ප්‍රතිපත්ති ඉදිරිපත් කිරීම.", listOf("විපක්ෂයේ කාර්යභාරය (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "විධායකය, ව්‍යවස්ථාදායකය සහ අධිකරණය අතර බලය බෙදී යාමේ වැදගත්කම ලියන්න.", 4, "ඒකාධිකාරී පාලනයක් වැළැක්වීම සහ බලය අයුසි ලෙස භාවිතය නැවැත්වීම.", listOf("බලය බෙදීමේ වැදගත්කම (ලකුණු 4)"))
      )
      3 -> listOf(
        StructuredSubQuestion("(i)", "$theme මානව හිමිකම් සහ මූලික අයිතිවාසිකම් අතර ඇති සම්බන්ධතාවය පැහැදිලි කරන්න.", 3, "ආණ්ඩුක්‍රම ව්‍යවස්ථාව මඟින් නීත්‍යානුකූලව තහවුරු කර ඇති අයිතිවාසිකම් වීම.", listOf("සම්බන්ධතාවය (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාව මඟින් සහතික කර ඇති ප්‍රධාන අයිතිවාසිකම් 2ක් නම් කරන්න.", 4, "1. සමානාත්මතාවයේ අයිතිය.\n2. ਵਿਚාර ප්‍රකාශ කිරීමේ නිදහස.", listOf("පළමු අයිතිය (ලකුණු 2)", "දෙවන අයිතිය (ලකුණු 2)")),
        StructuredSubQuestion("(iii)", "අයිතිවාසිකම් සමඟ බැඳී ඇති මූලික යුතුකම් මොනවාද?", 4, "අන් අයගේ නිදහසට ගරු කිරීම සහ ජාතික එකමුතුකම ආරක්ෂා කිරීම.", listOf("යුතුකම් පැහැදිලි කිරීම (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "මූලික අයිතිවාසිකම් උල්ලංඝනය වූ විට නීතිමය වශයෙන් ගත හැකි ක්‍රියාමාර්ගය කුමක්ද?", 3, "ශ්‍රේෂ්ඨාධිකරණය වෙත මූලික අයිතිවාසිකම් පෙтиමක් ඉදිරිපත් කිරීම.", listOf("නීතිමය ක්‍රියාමාර්ගය (ලකුණු 3)"))
