  private fun getCommerceSubQuestions(theme: String, q: Int): List<StructuredSubQuestion> {
    return when (q % 5) {
      1 -> listOf(
        StructuredSubQuestion("(i)", "$theme ව්‍යාපාරික සංකල්පය හෝ මූලික ගිණුම්කරණ සමීකරණය ලියන්න.", 3, "වත්කම් = හිමිකම + වගකීම් (Assets = Capital + Liabilities).", listOf("සමීකරණය නිවැරදිව ලිවීම (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "ව්‍යාපාරයක මූලික අරමුණු 2ක් ලියන්න.", 4, "1. ලාභ ඉපැයීම.\n2. සමාජීය වගකීම් ඉටු කරමින් අඛණ්ඩව පැවැත්ම.", listOf("පළමු අරමුණ (ලකුණු 2)", "දෙවන අරමුණ (ලකුණු 2)")),
        StructuredSubQuestion("(iii)", "ව්‍යාපාරයක මූල්‍ය තත්ත්වය පෙන්වන ප්‍රධාන ප්‍රකාශනය කුමක්ද?", 4, "මූල්‍ය තත්ත්ව ප්‍රකාශය (Balance Sheet / Statement of Financial Position).", listOf("ප්‍රකාශනය නම් කිරීම (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "ව්‍යාපාරයක සාර්ථකත්වයට යහපත් කළමනාකරණයක් අවශ්‍ය වන්නේ ඇයි?", 3, "සම්පත් ප්‍රශස්ථව යොදවා කාර්යක්ෂමතාව ඉහළ නංවා ගැනීමට.", listOf("අවශ්‍යතාව (ලකුණු 3)"))
      )
      2 -> listOf(
        StructuredSubQuestion("(i)", "$theme ද්විත්ව සටහන් තැබීමේ මූලධර්මය (Double Entry Principle) හැඳින්වීම.", 3, "සෑම මූල්‍ය ගනුදෙනුවකම හර (Debit) සහ බැර (Credit) යන දෙපැත්තම සමානව සටහන් කිරීම.", listOf("මූලධර්මය (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "මූලාශ්‍ර ලේඛන (Source documents) 2ක් නම් කරන්න.", 4, "1. ඉන්වොයිසිය (Invoice).\n2. රිසිට්පත (Receipt).", listOf("පළමු ලේඛනය (ලකුණු 2)", "දෙවන ලේඛනය (ලකුණු 2)")),
        StructuredSubQuestion("(iii)", "මුල් සටහන් පොත්වල (Books of Original Entry) ප්‍රයෝජනය කුමක්ද?", 4, "විවිධ ගනුදෙනු වර්ගීකරණය කර ප්‍රධාන ලේජරයට ඇතුළත් කිරීමට පෙර පහසුකම් සැලසීම.", listOf("ප්‍රයෝජනය (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "ශේෂ පරීක්ෂාවක (Trial Balance) මූලික අරමුණ ලියන්න.", 4, "ද්විත්ව සටහන්වල ගණිතමය නිරවද්‍යතාව පරීක්ෂා කිරීම.", listOf("මූලික අරමුණ (ලකුණු 4)"))
      )
      3 -> listOf(
        StructuredSubQuestion("(i)", "$theme අලෙවිකරණ මුلط්ව (Marketing Mix - 4Ps) අතුරින් ප්‍රධාන අංග 2ක් නම් කරන්න.", 3, "නිෂ්පාදනය (Product), මිල (Price), ස්ථානය (Place), ප්‍රවර්ධනය (Promotion).", listOf("අංග 2ක් නම් කිරීම (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "වෙළඳ දැන්වීම්කරණයේ (Advertising) ව්‍යාපාරික වැදගත්කම ලියන්න.", 4, "පාරිභෝගිකයන් දැනුවත් කිරීම සහ භාණ්ඩ අලෙවිය ඉහළ නංවා ගැනීම.", listOf("වැදගත්කම (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "සැපයුම් දාම කළමනාකරණයේ (Supply Chain) ප්‍රධාන පියවරක් විස්තර කරන්න.", 4, "අමුද්‍රව්‍ය ලබාගැනීමේ සිට නිමි භාණ්ඩ පාරිභෝගිකයා වෙත ළඟා කරවීම දක්වා ක්‍රියාවලිය.", listOf("පියවර විස්තර කිරීම (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "විද්‍යුත් වාණිජ්‍යය (E-Commerce) ව්‍යාපාරවලට ලබාදී ඇති වාසිය කුමක්ද?", 3, "ගෝලීය වෙළඳපොළකට සෘජුවම ප්‍රවේශ වීමේ හැකියාව.", listOf("වාසිය (ලකුණු 3)"))
      )
      4 -> listOf(
        StructuredSubQuestion("(i)", "$theme මූල්‍ය කළමනාකරණයේ මුදල් ප්‍රවාහ ප්‍රකාශනයක (Cash Flow Statement) ඇති වැදගත්කම කුමක්ද?", 3, "ව්‍යාපාරයට ලැබෙන සහ පිටවන මුදල් A/C ශේෂයන් නිවැරදිව පෙන්වීම.", listOf("වැදගත්කම (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "ස්ථාවර වත්කම් සහ ජංගම වත්කම් අතර වෙනස නිදසුන් සහිතව දක්වන්න.", 4, "ස්ථාවර: දිගුකාලීන (ගොඩනැගිලි). ජංගම: කෙටිකාලීන (මුදල්, තොග).", listOf("වෙනස පැහැදිලි කිරීම (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "ශුද්ධ ලාභය සහ දළ ලාභය අතර වෙනස ලියන්න.", 4, "දළ ලාභය = විකුණුම් - විකුණන ලද භාණ්ඩවල පිරිවැය. ශුද්ධ ලාභය = දළ ලාභය + අනෙකුත් ආදායම් - වියදම්.", listOf("වෙනස දැක්වීම (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "ව්‍යාපාරික ආචාරධර්ම (Business Ethics) පවත්වාගැනීමේ අවශ්‍යතාව කුමක්ද?", 4, "දිගුකාලීන පාරිභෝගික විශ්වාසය සහ සමාජීය පිළිගැනීම දිනාගැනීම.", listOf("අවශ්‍යතාව (ලකුණු 4)"))
      )
      else -> listOf(
        StructuredSubQuestion("(i)", "$theme මූල්‍ය ආයතන අතර වාණිජ බැංකුවල ප්‍රධාන කාර්යභාරය කුමක්ද?", 3, "ජනතාවගෙන් තැන්පත් භාරගැනීම සහ ණය ලබාදීම.", listOf("කාර්යභාරය (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "මධ්‍යම බැංකුව (Central Bank) රටක ආර්ථිකය පාලනය කරන ආකාරය ලියන්න.", 4, "මූල්‍ය ප්‍රතිපත්ති මෙහෙයවීම සහ මුදල් නෝට්ටු මුද්‍රණය කිරීමේ ඒකාධිකාරය දැරීම.", listOf("මධ්‍යම බැංකු කාර්යය (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "උද්ධමනය (Inflation) නිසා ජනතාවගේ ජීවන තත්ත්වයට වන බලපෑම කුමක්ද?", 4, "මුදලේ අගය අඩුවීම සහ ජීවන වියදම ඉහළ යාම.", listOf("බලපෑම (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "කුඩා හා මධ්‍ය පරිමාණ ව්‍යාපාර (SMEs) රටේ ආර්ථිකයට දායක වන්නේ කෙසේද?", 3, "රැකියා උත්පාදනය සහ දේශීය සම්පත් උපරිමයෙන් ප්‍රයෝජනයට ගැනීම.", listOf("දායකත්වය (ලකුණු 3)"))
      )
    }
  }

  private fun getScienceSubQuestions(theme: String, q: Int): List<StructuredSubQuestion> {
    return listOf(
      StructuredSubQuestion("(i)", "$theme හි ප්‍රධාන විද්‍යාත්මක නිර්වචනය හා හරය ප්‍රකාශ කරන්න.", 3, "$theme යටතේ විභාග මට්ටමේ නිල නිර්වචනය සහ පාරිභාෂික අර්ථය.", listOf("නිර්වචනය නිවැරදිව ලිවීම (ලකුණු 2)", "පාරිභාෂික නිරවද්‍යතාව (ලකුණු 1)")),
      StructuredSubQuestion("(ii)", "අදාළ සංකල්පයට අදාළ මූලික සංරචක හෝ සාධක 2ක් නම් කරන්න.", 4, "1. පළමු විචල්‍යය හෝ සංරචකය.\n2. දෙවන මූලික සංරචකය.", listOf("පළමු සාධකය (ලකුණු 2)", "දෙවන සාධකය (ලකුණු 2)")),
      StructuredSubQuestion("(iii)", "මෙම සංකල්පය තහවුරු කරගැනීමට පරීක්ෂණාත්මකව කළ හැකි නිරීක්ෂණය කුමක්ද?", 4, "පැහැදිලි වර්ණ විපර්යාසයක් හෝ පාඨාංක වෙනසක් නිරීක්ෂණය වීම.", listOf("නිරීක්ෂණය (ලකුණු 2)", "නිගමනය (ලකුණු 2)")),
      StructuredSubQuestion("(iv)", "මෙම විද්‍යාත්මක න්‍යාය එදිනෙදා ජීවිතයේදී යොදාගන්නා වැදගත් ප්‍රායෝගික අවස්ථාවක් දක්වන්න.", 4, "තාක්ෂණික උපකරණවල හෝ කාර්මික ක්‍රියාවලීන්හි භාවිතය.", listOf("ප්‍රායෝගික යෙදුම (ලකුණු 4)"))
    )
  }

  private fun getMathSubQuestions(theme: String, q: Int): List<StructuredSubQuestion> {
    return listOf(
      StructuredSubQuestion("(i)", "$theme ගැටලුව විසඳීමට අදාළ මූලික ගණිතමය සූත්‍රය හෝ සිද්ධාන්තය ලියන්න.", 3, "අදාළ සිද්ධාන්තය හෝ සූත්‍රය නිවැරදිව ලිවීම.", listOf("සූත්‍රය / සිද්ධාන්තය (ලකුණු 3)")),
      StructuredSubQuestion("(ii)", "ලබා දී ඇති දත්ත සූත්‍රයට ආදේශ කර ප්‍රථම පියවරේ සුළු කිරීම සිදු කරන්න.", 4, "දත්ත නිවැරදිව ආදේශ කර අනුක්‍රමිකව සුළු කිරීම.", listOf("දත්ත ආදේශනය (ලකුණු 2)", "සුළු කිරීම (ලකුණු 2)")),
      StructuredSubQuestion("(iii)", "අවසාන පිළිතුර සම්මත ඒකකය හෝ නිවැරදි දශමස්ථානය සහිතව ගණනය කරන්න.", 4, "අවසාන අගය නිවැරදිව ලබාගැනීම.", listOf("ගණනය කිරීම (ලකුණු 4)")),
      StructuredSubQuestion("(iv)", "ගණනය කළ ප්‍රතිඵලය ජ්‍යාමිතිකව හෝ වීජීයව තහවුරු කරන්න.", 4, "ප්‍රතිඵලයේ තාර්කික බව පෙන්වා දීම.", listOf("තහවුරු කිරීම (ලකුණු 4)"))
    )
  }

  private fun getIctSubQuestions(theme: String, q: Int): List<StructuredSubQuestion> {
    return listOf(
      StructuredSubQuestion("(i)", "$theme පරිගණක තාක්ෂණ සංකල්පය හඳුන්වා දෙන්න.", 3, "මූලික අර්ථ දැක්වීම සහ ක්‍රියාකාරීත්වය.", listOf("නිර්වචනය (ලකුණු 3)")),
      StructuredSubQuestion("(ii)", "අදාළ මෘදුකාංග හෝ දෘඩාංග අංග 2ක් නම් කරන්න.", 4, "1. ආදාන/ප්‍රතිදාන උපකරණ.\n2. ක්‍රමලේඛන භාෂාව හෝ දත්ත සමුදාය.", listOf("පළමු අංගය (ලකුණු 2)", "දෙවන අංගය (ලකුණු 2)")),
      StructuredSubQuestion("(iii)", "මෙම තාක්ෂණය භාවිතයේ ඇති ප්‍රධාන වාසිය සහ ආරක්ෂක උපායමාර්ගය ලියන්න.", 4, "වාසිය: වේගවත් දත්ත සැකසීම.\nආරක්ෂාව: දත්ත සංකේතනය (Encryption) සහ මුරපද භාවිතය.", listOf("වාසිය (ලකුණු 2)", "ආරක්ෂාව (ලකුණු 2)")),
      StructuredSubQuestion("(iv)", "නවීන තොරතුරු සමාජයේ මෙහි වැදගත්කම විග්‍රහ කරන්න.", 4, "සන්නිවේදනය පහසු වීම සහ ඩිජිටල් සේවා පුළුල් වීම.", listOf("විග්‍රහය (ලකුණු 4)"))
    )
  }

  private fun getGeneralSubQuestions(theme: String, q: Int): List<StructuredSubQuestion> {
    return listOf(
      StructuredSubQuestion("(i)", "$theme හි ප්‍රධාන සංකල්පය සහ අර්ථය පැහැදිලි කරන්න.", 3, "මූලික අර්ථ දැක්වීම.", listOf("අර්ථ දැක්වීම (ලකුණු 3)")),
      StructuredSubQuestion("(ii)", "අදාළ ක්ෂේත්‍රයේ ප්‍රධාන අංග හෝ ලක්ෂණ 2ක් නම් කරන්න.", 4, "1. පළමු ලක්ෂණය.\n2. දෙවන ලක්ෂණය.", listOf("පළමු ලක්ෂණය (ලකුණු 2)", "දෙවන ලකුණු (ලකුණු 2)")),
      StructuredSubQuestion("(iii)", "මෙම විෂය කරුණ සමාජීය වශයෙන් වැදගත් වන්නේ ඇයි?", 4, "මානව ජීවිතයට සහ සංවර්ධනයට සෘජුව දායක වීම.", listOf("වැදගත්කම (ලකුණු 4)")),
      StructuredSubQuestion("(iv)", "අදාළ මාතෘකාව ආශ්‍රිතව නිගමනයක් ලියන්න.", 4, "විෂය කරුණ සාරාංශගත කිරීම.", listOf("නිගමනය (ලකුණු 4)"))
    )
  }
}
